function ods_to_csf_formula(f3) {
  if (f3.slice(0, 3) == "of:")
    f3 = f3.slice(3);
  if (f3.charCodeAt(0) == 61) {
    f3 = f3.slice(1);
    if (f3.charCodeAt(0) == 61)
      f3 = f3.slice(1);
  }
  f3 = f3.replace(/COM\.MICROSOFT\./g, "");
  f3 = f3.replace(/\[((?:\.[A-Z]+[0-9]+)(?::\.[A-Z]+[0-9]+)?)\]/g, function($$, $1) {
    return $1.replace(/\./g, "");
  });
  f3 = f3.replace(/\[.(#[A-Z]*[?!])\]/g, "$1");
  return f3.replace(/[;~]/g, ",").replace(/\|/g, ";");
}
